import subprocess,re
def syms(p):
    out=subprocess.run(['nm','-n',p],capture_output=True,text=True).stdout
    rows=[]
    for l in out.splitlines():
        m=re.match(r'^([0-9a-f]{16}) (\w) (.*)$',l)
        if m: rows.append((int(m.group(1),16),m.group(3)))
    rows.sort()
    d={}
    for i,(a,n) in enumerate(rows):
        sz=(rows[i+1][0]-a) if i+1<len(rows) else 0
        n=re.sub(r'17h[0-9a-f]{16}E$','',n)
        d[n]=d.get(n,0)+sz
    return d
a=syms('target/vm-sym/release/lypning'); b=syms('target/vl-sym/release/lypning')
delta=[(b.get(k,0)-a.get(k,0),k) for k in set(a)|set(b)]
delta.sort(reverse=True)
print('sum of positive deltas:',sum(d for d,_ in delta if d>0))
for d,k in delta[:18]: print('%7d  %s'%(d,k))

